/**
 * turntable — producto en 360° hecho con cuadros (una vuelta completa) en un
 * <canvas>, con fundido entre cuadros. Gira solo, se arrastra y sigue con
 * inercia. Con giro automático lento se nota el pulso entre ángulos: si el
 * giro es protagonista, usá `model-turntable`.
 * Familia: 3D / producto · Intensidad 2 · 0 deps.
 *
 *   <figure data-fx-turntable>
 *     <canvas data-fx-canvas></canvas>
 *     <img data-fx-fallback src="spin-001.webp" alt="El producto, de frente">
 *
 * Reduced motion: no gira solo ni tiene inercia.
 * destroy(): suelta imágenes y listeners y devuelve canvas y fallback como estaban.
 */

import { bundle, part, preserve, type FxHandle } from '../../core/index';
import { createFramePlayer, frameUrls, loadOrder, type Frames } from '../../lib/frame-player';
import { createSpinControl, type SpinControlOptions } from '../../lib/spin-control';

export interface TurntableOptions extends Partial<Pick<SpinControlOptions, 'input' | 'auto' | 'turnSeconds' | 'label'>> {
  /** Una vuelta completa; el último cuadro justo antes del primero. */
  frames: Frames;
  canvas?: HTMLCanvasElement | null;
  fallback?: HTMLElement | null;
  fit?: 'contain' | 'cover';
  startFrame?: number;
  onFrame?: (index: number, turn: number) => void;
}

export function createTurntable(root: HTMLElement, options: TurntableOptions): FxHandle {
  const canvas = options.canvas ?? (root instanceof HTMLCanvasElement ? root : part<HTMLCanvasElement>(root, 'canvas'));
  const fallback = options.fallback ?? part(root, 'fallback');
  const urls = frameUrls(options.frames);
  const n = urls.length;
  if (!canvas || !n || !canvas.getContext('2d')) return { destroy() {} };

  const player = createFramePlayer({ canvas, urls, fit: options.fit ?? 'contain' });
  const restore = bundle(fallback && preserve(fallback, { attributes: ['hidden'] }));
  fallback?.setAttribute('hidden', '');
  player.resize();

  let shown = -1;
  const control = createSpinControl({
    el: canvas,
    input: options.input,
    auto: options.auto,
    turnSeconds: options.turnSeconds,
    label: options.label,
    start: (options.startFrame ?? 0) / n,
    onTurn: (turn) => {
      const pos = turn * n;
      player.show(pos, true);
      const i = Math.round(pos) % n;
      if (i !== shown) {
        shown = i;
        options.onFrame?.(i, turn);
      }
    },
  });
  player.loadWhenNear(canvas, () => loadOrder(n, Math.round(control.turn * n) % n));
  const onResize = () => player.resize();
  addEventListener('resize', onResize, { passive: true });

  return {
    destroy() {
      control.destroy();
      removeEventListener('resize', onResize);
      player.destroy();
      restore();
    },
  };
}

'use client';

import type { DependencyList, RefObject } from 'react';
import { useFx } from '../../core/react';
import type { FxHandle } from '../../core/types';
import { createTurntable, type TurntableOptions } from './index';

/**
 * Hook de `turntable`. Monta sobre `ref.current` y destruye al desmontar.
 * Las opciones se leen al montar; pasá `deps` para volver a montar cuando cambien.
 */
export function useTurntable<E extends HTMLElement>(
  ref: RefObject<E | null>,
  options: TurntableOptions,
  deps: DependencyList = [],
): RefObject<FxHandle | null> {
  return useFx(ref, (el) => createTurntable(el, options), deps);
}

/**
 * Reproductor de secuencias de imágenes sobre un <canvas>: carga progresiva,
 * dibujo con devicePixelRatio, el cuadro cargado más cercano mientras falta
 * el pedido y fundido entre cuadros vecinos. No decide qué mostrar: eso lo
 * hacen `scroll-sequence` y `turntable`.
 */

import { whenNear } from '../core/index';

/** Orden de carga: primero el cuadro que se va a ver, después cada 8º, cada 4º y el resto. */
export function loadOrder(n: number, first: number): number[] {
  const seen = new Set([first]);
  const out = [first];
  for (const step of [8, 4, 1]) {
    for (let i = 0; i < n; i += step) {
      if (!seen.has(i)) {
        seen.add(i);
        out.push(i);
      }
    }
  }
  return out;
}

export type Frames = string[] | { count: number; src: (i: number) => string };

export const frameUrls = (frames: Frames): string[] =>
  Array.isArray(frames) ? frames.slice() : Array.from({ length: frames.count }, (_, i) => frames.src(i));

export interface FramePlayer {
  readonly count: number;
  /** Posición con decimales: `12.4` funde el 12 con el 13 al 40%. `wrap` = bucle. */
  show(pos: number, wrap?: boolean): void;
  resize(): void;
  /** Empieza a cargar cuando `el` queda a ~1 pantalla. `order` se evalúa al disparar. */
  loadWhenNear(el: Element, order: () => number[]): void;
  destroy(): void;
}

export function createFramePlayer({
  canvas,
  urls,
  fit = 'contain',
  concurrency = 6,
}: {
  canvas: HTMLCanvasElement;
  urls: string[];
  fit?: 'contain' | 'cover';
  concurrency?: number;
}): FramePlayer {
  const n = urls.length;
  const ctx = canvas.getContext('2d');
  let imgs: (HTMLImageElement | null)[] = new Array(n).fill(null);
  const inFlight = new Set<HTMLImageElement>();
  let queue: number[] = [];
  let offNear: (() => void) | null = null;
  let active = 0;
  let dead = false;
  let want = 0;
  let mix = 0;
  let loop = false;
  let drawn = '';

  const nearest = (i: number) => {
    if (imgs[i]) return i;
    for (let d = 1; d < n; d++) {
      if (i - d >= 0 && imgs[i - d]) return i - d;
      if (i + d < n && imgs[i + d]) return i + d;
    }
    return -1;
  };
  const paintImg = (img: HTMLImageElement, alpha: number) => {
    if (!ctx) return;
    const { width: W, height: H } = canvas;
    const s = (fit === 'cover' ? Math.max : Math.min)(W / img.naturalWidth, H / img.naturalHeight);
    const dw = img.naturalWidth * s;
    const dh = img.naturalHeight * s;
    ctx.globalAlpha = alpha;
    ctx.drawImage(img, (W - dw) / 2, (H - dh) / 2, dw, dh);
    ctx.globalAlpha = 1;
  };
  const draw = () => {
    if (!ctx) return;
    const i = nearest(want);
    if (i < 0) return; // sin cuadros todavía: queda lo que hubiera
    const next = loop ? (i + 1) % n : i + 1;
    const nextImg = next < n ? imgs[next] : null;
    const f = i === want && mix > 0.02 && nextImg ? Math.round(mix * 32) / 32 : 0;
    const key = `${i}:${f}`;
    if (key === drawn) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Base opaca y siguiente encima con alfa: el objeto nunca se vuelve translúcido.
    paintImg(imgs[i] as HTMLImageElement, 1);
    if (f && nextImg) paintImg(nextImg, f);
    drawn = key;
  };
  const resize = () => {
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = Math.round(canvas.clientWidth * dpr);
    const h = Math.round(canvas.clientHeight * dpr);
    if (w !== canvas.width || h !== canvas.height) {
      canvas.width = w;
      canvas.height = h;
      drawn = '';
    }
    draw();
  };
  const pump = () => {
    while (!dead && active < concurrency && queue.length) {
      const i = queue.shift() as number;
      const img = new Image();
      img.decoding = 'async';
      img.src = urls[i] as string;
      inFlight.add(img);
      active++;
      img
        .decode()
        .then(() => {
          if (dead) return;
          imgs[i] = img;
          draw();
        })
        .catch(() => {}) // un cuadro roto no corta nada: se usa el vecino
        .finally(() => {
          inFlight.delete(img);
          active--;
          pump();
        });
    }
  };

  return {
    count: n,
    show(pos, wrap = false) {
      loop = wrap;
      const p = wrap ? ((pos % n) + n) % n : Math.min(n - 1, Math.max(0, pos));
      want = Math.floor(p);
      mix = p - want;
      draw();
    },
    resize,
    loadWhenNear(el, order) {
      offNear = whenNear(el, () => {
        queue = order();
        pump();
      });
    },
    destroy() {
      dead = true;
      offNear?.();
      queue = [];
      for (const img of inFlight) img.src = '';
      for (const img of imgs) if (img) img.src = '';
      inFlight.clear();
      imgs = [];
      ctx?.clearRect(0, 0, canvas.width, canvas.height);
    },
  };
}

/**
 * Control de giro para un objeto en 360°: gira solo, se arrastra con el mouse
 * o el dedo, sigue con inercia, retoma el giro solo y responde a las flechas.
 * No dibuja: llama a `onTurn(vuelta)` y el host pinta.
 *
 * Reduced motion: no gira solo ni tiene inercia (en vivo).
 * El elemento es un slider enfocable; ← → giran de a 15°. En touch el arrastre
 * vertical sigue scrolleando (pan-y). Fuera de pantalla no hay rAF.
 */

import { createLoop, onVisibility, preserve, prefersReducedMotion } from '../core/index';

export interface SpinControlOptions {
  el: HTMLElement;
  input?: 'drag' | 'hover';
  auto?: boolean;
  /** Segundos por vuelta en el giro automático. */
  turnSeconds?: number;
  /** Fracción de vuelta inicial. */
  start?: number;
  label?: string;
  onTurn: (turn: number) => void;
}

export interface SpinControl {
  readonly turn: number;
  destroy(): void;
}

export function createSpinControl({
  el,
  input = 'drag',
  auto = true,
  turnSeconds = 14,
  start = 0,
  label = 'Producto en 360°: arrastrá o usá las flechas para girarlo',
  onTurn,
}: SpinControlOptions): SpinControl {
  const autoVel = () => (auto && !prefersReducedMotion() ? 1 / turnSeconds : 0);
  let angle = start;
  let vel = 0;
  let dragging = false;
  let lastX = 0;
  let lastT = 0;
  let idleUntil = 0;
  let visible = false;
  let deg = -1;

  const turn = () => ((angle % 1) + 1) % 1;
  const emit = () => {
    const t = turn();
    onTurn(t);
    const d = Math.round(t * 360) % 360;
    if (d !== deg) {
      deg = d;
      el.setAttribute('aria-valuenow', String(d));
    }
  };
  const loop = createLoop((dt, now) => {
    if (!dragging) {
      const want = now > idleUntil ? autoVel() : 0;
      vel += (want - vel) * (1 - Math.pow(0.05, dt));
      angle += vel * dt;
    }
    emit();
    return visible && (dragging || Math.abs(vel) > 1e-4 || autoVel() > 0);
  });
  const kick = () => {
    if (visible) loop.wake();
  };

  const perPx = () => 0.5 / Math.max(1, el.clientWidth); // un ancho ≈ media vuelta
  const onDown = (e: PointerEvent) => {
    dragging = true;
    vel = 0;
    lastX = e.clientX;
    lastT = e.timeStamp;
    el.setPointerCapture?.(e.pointerId);
    kick();
  };
  const onMove = (e: PointerEvent) => {
    const hover = input === 'hover' && e.pointerType === 'mouse';
    if (!dragging && !hover) return;
    if (hover && !dragging && !lastT) [lastX, lastT] = [e.clientX, e.timeStamp];
    const dx = e.clientX - lastX;
    const dt = Math.max(1, e.timeStamp - lastT) / 1000;
    angle -= dx * perPx();
    vel = prefersReducedMotion() ? 0 : vel * 0.6 + ((-dx * perPx()) / dt) * 0.4;
    lastX = e.clientX;
    lastT = e.timeStamp;
    idleUntil = performance.now() + 2500;
    emit();
    kick();
  };
  const onUp = () => {
    dragging = false;
    if (prefersReducedMotion()) vel = 0;
    idleUntil = performance.now() + 2500;
  };
  const onLeave = (e: PointerEvent) => {
    if (e.pointerType === 'mouse' && !dragging) lastT = 0;
  };
  const onKey = (e: KeyboardEvent) => {
    const dir = e.key === 'ArrowLeft' ? -1 : e.key === 'ArrowRight' ? 1 : 0;
    if (!dir) return;
    e.preventDefault();
    angle += dir / 24;
    vel = 0;
    idleUntil = performance.now() + 4000;
    emit();
    kick();
  };

  const restore = preserve(el, {
    attributes: ['tabindex', 'role', 'aria-label', 'aria-valuemin', 'aria-valuemax', 'aria-valuenow'],
    styles: ['touch-action'],
  });
  el.tabIndex = 0;
  el.setAttribute('role', 'slider');
  el.setAttribute('aria-label', label);
  el.setAttribute('aria-valuemin', '0');
  el.setAttribute('aria-valuemax', '359');
  el.style.touchAction = 'pan-y';

  emit();
  el.addEventListener('pointerdown', onDown);
  el.addEventListener('pointermove', onMove);
  el.addEventListener('pointerup', onUp);
  el.addEventListener('pointercancel', onUp);
  el.addEventListener('pointerleave', onLeave);
  el.addEventListener('keydown', onKey);
  const offVisible = onVisibility(el, (v) => {
    visible = v;
    if (v) kick();
  });

  return {
    get turn() {
      return turn();
    },
    destroy() {
      el.removeEventListener('pointerdown', onDown);
      el.removeEventListener('pointermove', onMove);
      el.removeEventListener('pointerup', onUp);
      el.removeEventListener('pointercancel', onUp);
      el.removeEventListener('pointerleave', onLeave);
      el.removeEventListener('keydown', onKey);
      offVisible();
      loop.stop();
      visible = false;
      restore();
    },
  };
}
